const a=new Intl.NumberFormat("ru-RU",{style:"currency",currency:"RUB",maximumFractionDigits:0});function u(t){return a.format(t)}function c(t,n){return`${n==="income"?"+":"−"} ${a.format(t)}`}function o(t){return new Date(t).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}function i(t){const n=new Date(t),e=new Date,r=new Date;return r.setDate(e.getDate()-1),n.toDateString()===e.toDateString()?"Сегодня":n.toDateString()===r.toDateString()?"Вчера":n.toLocaleDateString("ru-RU",{day:"numeric",month:"long"})}function m(t){return`${i(t)}, ${o(t)}`}function f(){return new Date().toLocaleDateString("ru-RU",{weekday:"long",day:"numeric",month:"long"})}function g(t,n){return n<=0?null:Math.round((t-n)/n*100)}export{c as a,o as b,i as c,g as d,m as e,u as f,f as t};
